model Ball {
  id: ID
  x: Number
  y: Number
  vx: Number
  vy: Number
  radius: Number = 10
}

component BallSimulation {
  state balls: Ball[] = []
  state isRunning = true
  state frameCount = 0
  ref canvas
  ref animationId

  fn initializeBalls {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: (Math.random() - 0.5) * 4,
        vy: (Math.random() - 0.5) * 4,
        radius: 10
      })
    }
    frameCount = 0
  }

  fn addBall {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: (Math.random() - 0.5) * 4,
      vy: (Math.random() - 0.5) * 4,
      radius: 10
    })
  }

  fn togglePause {
    isRunning = !isRunning
  }

  fn applyGravity {
    for b in balls {
      b.vy += 0.2
    }
  }

  fn checkBoundaryCollisions {
    for b in balls {
      if b.x - b.radius < 0 {
        b.x = b.radius
        b.vx = -b.vx
      }
      if b.x + b.radius > 400 {
        b.x = 400 - b.radius
        b.vx = -b.vx
      }
      if b.y - b.radius < 0 {
        b.y = b.radius
        b.vy = -b.vy
      }
      if b.y + b.radius > 300 {
        b.y = 300 - b.radius
        b.vy = -b.vy
      }
    }
  }

  fn checkBallCollisions {
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let b1 = balls[i]
        let b2 = balls[j]
        let dx = b2.x - b1.x
        let dy = b2.y - b1.y
        let distance = Math.sqrt(dx * dx + dy * dy)

        if distance < b1.radius + b2.radius {
          let temp_vx = b1.vx
          let temp_vy = b1.vy
          b1.vx = b2.vx
          b1.vy = b2.vy
          b2.vx = temp_vx
          b2.vy = temp_vy
        }
      }
    }
  }

  fn updatePositions {
    for b in balls {
      b.x += b.vx
      b.y += b.vy
    }
  }

  fn draw {
    let ctx = canvas.getContext("2d")
    ctx.fillStyle = "#ffffff"
    ctx.fillRect(0, 0, 400, 300)

    ctx.fillStyle = "#e11d48"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn simulate {
    if isRunning {
      applyGravity()
      checkBoundaryCollisions()
      checkBallCollisions()
      updatePositions()
      frameCount++
    }
    draw()
    animationId = requestAnimationFrame(simulate)
  }

  mount {
    initializeBalls()
    draw()
    simulate()
    cleanup {
      if animationId {
        cancelAnimationFrame(animationId)
      }
    }
  }

  column gap=4 pad=4 {
    row gap=4 align=center {
      title "Simulador de Pelotas" tag=h1
    }
    row gap=4 {
      button "Agregar" primary -> addBall()
      button (isRunning ? "Pausar" : "Reanudar") -> togglePause()
      button "Reiniciar" danger -> initializeBalls()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}` bold
      text `Cuadros: ${frameCount}` bold
    }
    canvas ref=canvas width=400 height=300 style="border: 2px solid #666; display: block; background: white;"
  }
}

