model Ball {
  id: ID
  x: Number
  y: Number
  vx: Number
  vy: Number
  radius: Number = 10
}

component BallSimulation {
  ref canvas
  state balls: Ball[] = []
  state paused = false
  state frames = 0
  state animationId = null

  fn initBalls {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 8,
        radius: 10
      })
    }
    frames = 0
  }

  fn addBall {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 8,
      radius: 10
    })
  }

  fn togglePause {
    paused = !paused
  }

  fn updatePhysics {
    const gravity = 0.2

    for (let i = 0; i < balls.length; i++) {
      const ball = balls[i]
      ball.vy += gravity

      ball.x += ball.vx
      ball.y += ball.vy

      if (ball.x - ball.radius < 0) {
        ball.x = ball.radius
        ball.vx = -ball.vx
      }
      if (ball.x + ball.radius > 400) {
        ball.x = 400 - ball.radius
        ball.vx = -ball.vx
      }
      if (ball.y - ball.radius < 0) {
        ball.y = ball.radius
        ball.vy = -ball.vy
      }
      if (ball.y + ball.radius > 300) {
        ball.y = 300 - ball.radius
        ball.vy = -ball.vy
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const b1 = balls[i]
        const b2 = balls[j]
        const dx = b2.x - b1.x
        const dy = b2.y - b1.y
        const dist = Math.sqrt(dx * dx + dy * dy)

        if (dist < b1.radius + b2.radius) {
          const temp_vx = b1.vx
          const temp_vy = b1.vy
          b1.vx = b2.vx
          b1.vy = b2.vy
          b2.vx = temp_vx
          b2.vy = temp_vy

          const overlap = b1.radius + b2.radius - dist
          const nx = dx / dist
          const ny = dy / dist
          b1.x -= (overlap / 2) * nx
          b1.y -= (overlap / 2) * ny
          b2.x += (overlap / 2) * nx
          b2.y += (overlap / 2) * ny
        }
      }
    }
  }

  fn drawBalls {
    const ctx = canvas.getContext("2d")
    ctx.fillStyle = "#ffffff"
    ctx.fillRect(0, 0, 400, 300)

    ctx.fillStyle = "#2563eb"
    for (let i = 0; i < balls.length; i++) {
      const ball = balls[i]
      ctx.beginPath()
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2)
      ctx.fill()
    }

    ctx.strokeStyle = "#1e293b"
    ctx.lineWidth = 1
    ctx.strokeRect(0, 0, 400, 300)
  }

  fn animate {
    if (!paused) {
      updatePhysics()
      frames++
    }
    drawBalls()
    animationId = requestAnimationFrame(animate)
  }

  mount {
    initBalls()
    drawBalls()
    animate()
    cleanup {
      if (animationId) {
        cancelAnimationFrame(animationId)
      }
    }
  }

  row gap=4 pad=4 {
    column gap=2 {
      canvas ref=canvas width=400 height=300
    }
    column gap=3 {
      button "Agregar" primary -> addBall()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" danger -> initBalls()
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frames}`
    }
  }
}

